const menu = document.querySelector('.menu');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open)});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open')}));
const stages=[["01 / BIND & CLOSING", "Create the authoritative transaction record when business is bound."], ["02 / POLICIES", "Maintain the structured contract and risk record."], ["03 / ENDORSEMENTS", "Record every change without overwriting the original transaction."], ["04 / PREMIUM TRANSACTIONS", "Represent gross premium, commission, net premium, instalments and premium adjustments."], ["05 / BORDEREAUX", "Generate carrier-required reporting from the transaction record."], ["06 / SETTLEMENT OBLIGATIONS", "Determine what is due to each counterparty and link settlement information back to the underlying transactions."], ["07 / CONNECT", "Exchange structured transaction data through APIs, JSON, CSV/XLSX and documents."]];
document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});const [code,copy]=stages[Number(button.dataset.step)];document.querySelector('#step-code').textContent=code;document.querySelector('#step-copy').textContent=copy}));
const formats={JSON:['policy.json','{\n  "policy_id": "BRD-2026-0142",\n  "insured_value": 24500000,\n  "currency": "USD",\n  "coverage": "Hull & Machinery",\n  "status": "bound"\n}'],CSV:['bordereau.csv','policy_id,currency,insured_value,status\nBRD-2026-0142,USD,24500000,bound\n\nOne row derived from the structured record.\nColumns can follow a counterparty’s specification.'],XLSX:['bordereau.xlsx · content preview','POLICY REFERENCE     BRD-2026-0142\nCURRENCY             USD\nINSURED VALUE        24,500,000\nGROSS PREMIUM        4,703.29\nCOMMISSION           15%\nNET PREMIUM          3,997.79\n\nIllustrative workbook fields.'],PDF:['policy-schedule.pdf · content preview','POLICY SCHEDULE\n─────────────────────────────────\nReference     BRD-2026-0142\nRisk          MV Example Vessel\nCoverage      Hull & Machinery\nValue         USD 24,500,000\nPeriod        15 Jan 2026 – 14 Jul 2027\n\nIllustrative document content.'],API:['GET /policies/{id} · proposed interface','GET /policies/BRD-2026-0142\nAccept: application/json\n\n→ The same structured policy record.\n\nRelated event: policy.bound\n\nConcept only. No live API request is made.']};
document.querySelectorAll('[data-format]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-format]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});const [name,content]=formats[button.dataset.format];document.querySelector('#format-filename').textContent=name;document.querySelector('#format-content').textContent=content}));
document.querySelector('#format-content').setAttribute('aria-live','polite');
document.querySelector('#match').addEventListener('click',event=>{const button=event.currentTarget;button.disabled=true;document.querySelector('#match-status').textContent='Matching sample settlement…';setTimeout(()=>{document.querySelector('#match-status').textContent='Matched ✓ · Linked to the policy, endorsement, premium adjustment and carrier obligation.';button.disabled=false},900)});
document.querySelectorAll('[data-dialog]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.dialog).showModal()));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})});
document.querySelector('#partner-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const content=['BORDEON — Post-bind workflow conversation brief','Prepared locally. Not sent to Bordeon.','',...Array.from(data,([key,value])=>`${key}: ${value}`)].join('\n');const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='bordeon-conversation-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('.form-status').textContent='Your file is ready. Nothing has been sent. The details remain here until you close or reload this page.'});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open')}});
